custom_css:
/*
* 美化名字：熊猫计划
* 作者：一诺无悔
* 本样式免费发布于Discord尾巴镇。请勿二传或商用！
* 感谢@这对吗老师的"拼好码"，感谢旅程导航楼各位老师，代码引用皆有标注，不适配可以调root部分或问ai。
*/

/* === 字体 === */
@font-face {
  font-family: "Zidingyi";
  src: url("https://files.catbox.moe/c7d458.ttf") format("truetype");
  font-display: swap;
}

body {
  font-family: "Zidingyi";
  font-weight: normal;
}

button,
input,
textarea,
#send_textarea,
select,
button,
.text_pole,
.font-family-reset,
input[type="text"],
input[type="number"],
.search_field,
pre,
code,
.hljs,
pre code {
  font-family: inherit !important;
}

/* === 1. 全局配色与定义 === */
:root {
  /* 背景色：纯白 */
  --main-bg: #FFFFFF;
  /* 网页大背景 - 白 */

  /* 气泡卡片双色结构 */
  --card-header-bg: #F8F8F8;
  /* 上半部分：浅灰 */
  --card-body-bg: #FFFFFF;
  /* 下半部分：纯白 */
  --divider-color: #DDDDDD;
  /* 分割线颜色：浅灰 */

  /* --- 面板背景变量 --- */
  --panel-bg-image: url("https://i.postimg.cc/Z5bX1jZn/image_1770879379523.png");
  /* 面板背景图片 (保留) */
  --panel-bg-color: var(--bg-color) !important;
  /* 面板背景色: 防图片加载不出来 */
  --panel-bg-gradient: linear-gradient(rgba(255, 255, 255, 0.3), rgba(255, 255, 255, 0.3));
  /* 面板滤镜: 增白提亮 */

  /* 文字颜色：深灰/中灰 */
  --text-color: #222222;
  /* 深灰 */
  --text-sub: #777777;
  /* 中灰 */

  /* 仪表盘色块改为黑白灰阶 */
  --block-1: #F5F5F5;
  /* 亮白灰 */
  --block-2: #E8E8E8;
  /* 浅灰 */
  --block-3: #D8D8D8;
  /* 中灰 */
  --block-4: #C8C8C8;
  /* 深灰 */

  /* 角色标语：熊猫主题，第一行短，第二行长 */
  --char-slogan: "Panda Noir\A Embracing the monochrome.";
  /* 用户标语：第一行短，第二行长 */
  --user-slogan: "Daily Sketch\A Drawing with ink and paper.";

  /* --- UI 界面控件控制 --- */
  --chat-top-padding: 60px;
  /* 第一条消息距离顶部的距离 */
  --chat-bottom-padding: 120px;
  /* 最后一条消息底部避让距离 */
  --mes-block-width: 98%;
  /* 气泡宽度 */

  /* 底栏标语：熊猫梦 */
  --custom-placeholder: "✰. ˖𝒫𝒶𝓃𝒹𝒶 𝒟𝓇𝑒𝒶𝓂𝓈 ⁺₊˚๑";
  --placeholder-font-size: 13px;
  /* 🖋️ 调小字号 */
  --placeholder-left: 115px;
  /* 🖋️ 增加左边距，跳过左侧菜单图标 */
  --placeholder-top: 50%;
  /* 🖋️ 上下位置，百分比越高越靠下 */
}

body {
  background-color: var(--bg-color) !important;
  background-image: radial-gradient(#AAAAAA 1.5px, transparent 1.5px);
  /* 灰点阵，保留白底 */
  background-size: 24px 24px;
  color: var(--text-color);
}

.mes_text {
  line-height: 1.5 !important;
}

::-webkit-scrollbar {
  display: none !important;
}

/* 面板背景 */
.drawer-content {
  background-color: var(--panel-bg-color);
  border-radius: 0 !important;
  background-image: var(--panel-bg-gradient),
    var(--panel-bg-image) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border: none !important;
}

/* 移除白边 */
#chat,
.world_entry,
.wi-card-entry,
.world_entry_form {
  border: none !important;
  outline: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 菜单栏全屏化：@NA老师 */
.drawer-content.openDrawer {
  max-height: calc(100dvh - var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize));
  top: var(--topBarBlockSize) !important;
}

#left-nav-panel,
#right-nav-panel {
  height: 100dvh;
  max-height: 100dvh;
}

@media (max-width: 600px) {
  #right-nav-panel {
    max-height: calc(100dvh - var(--topBarBlockSize));
  }
}

* {
  scrollbar-width: none !important;
  /* Firefox */
  -ms-overflow-style: none !important;
  /* IE/Edge */
}

/* ===== 二、顶栏 ===== */

/* === 1. 顶栏背景：黑白细条纹 === */
#top-settings-holder {
  height: 30px !important;
  position: relative !important;
  background: repeating-linear-gradient(to right,
      #33333380,
      #33333380 3px,
      #FFFFFF80 3px,
      #FFFFFF80 6px) !important;
  border-bottom: 3px solid #888888 !important;
}

/* === 2. 顶栏图标：黑色描边/白色提升可读性 === */
#top-settings-holder .drawer-icon {
  color: #333333 !important;
  text-shadow:
    1px 1px 0px #FFF,
    -1px -1px 0px #FFF,
    1px -1px 0px #FFF,
    -1px 1px 0px #FFF,
    0px 2px 4px rgba(0, 0, 0, 0.2) !important;
  font-size: 16px !important;
  opacity: 1 !important;
}

#top-bar,
#top-settings-holder,
.top-bar-sticky {
  box-shadow: none !important;
  filter: none !important;
  text-shadow: none !important;
}

/* ===== 扩展栏 (Extensions Bar) 美化 - 黑白透明输入框版 ===== */
#extensionTopBar {
  position: fixed !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  width: auto !important;
  min-width: 200px !important;
  max-width: 95vw !important;
  height: 40px !important;
  background-color: #FFFFFF !important;
  background-size: 10px 10px !important;
  border: 2px solid #444444 !important;
  border-radius: 25px !important;
  padding: 4px 8px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 12px !important;
  z-index: 2000 !important;
  top: calc(var(--topBarBlockSize) + 10px) !important;
}

/* 扩展栏输入框与下拉框：强制透明且垂直居中 */
#extensionTopBar select,
#extensionTopBar input,
#extensionTopBar .text_pole,
#extensionConnectionProfiles select,
#extensionConnectionProfiles input {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  color: var(--text-color) !important;
  font-weight: 800 !important;
  margin: 0 !important;
  padding: 0 5px !important;
  height: 30px !important;
  line-height: 30px !important;
  display: inline-flex !important;
  align-items: center !important;
  vertical-align: middle !important;
}

/* 扩展栏内的功能图标按钮 */
#extensionTopBar .menu_button,
#extensionTopBar i {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: #444444 !important;
  font-size: 13px !important;
  transition: transform 0.2s ease;
}

/* 移动端适配：缩小间距 */
@media screen and (max-width: 600px) {
  #extensionTopBar {
    width: 95% !important;
    padding: 4px 10px !important;
    gap: 6px !important;
  }
}

/* ===== 三、底栏 ===== */
#form_sheld {
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 15px !important;
  width: 98% !important;
  z-index: 99 !important;
  overflow: visible !important;
  background: transparent !important;
  box-shadow: none !important;
}

/* 2. 输入框本体 */
#send_form,
body.no-blur #send_form {
  position: relative !important;
  background-color: #FFFFFF !important;
  background-image: none !important;
  opacity: 1 !important;
  border: 4px solid #444444 !important;
  border-radius: 30px !important;
  padding: 3px 6px !important;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1) !important;
  overflow: visible !important;
}

/* 小熊耳朵 */
#send_form::before {
  content: "" !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  width: 200px !important;
  height: 200px !important;
  top: -100px !important;
  background-image: url("https://i.postimg.cc/Y0ZNydx9/wu-biao-ti73-20260212112307.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: bottom center !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* 图标内部符号的大小适配 */
#options_button::before,
#extensionsMenuButton::before,
#quick-reply-rocket-button i::before,
#send_but::before {
  font-size: 18px !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 35px !important;
  width: 35px !important;
  line-height: 1 !important;
  vertical-align: middle !important;
}

/* 2. 输入区域：透明化 */
#send_textarea {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-family: inherit !important;
  margin: 0 !important;
  padding: 8px 10px !important;
  align-self: center !important;
  resize: none !important;
  min-height: 35px !important;
  line-height: 1.5 !important;
}

/* ===== 底栏全员垂直居中修正 ===== */
#nonQRFormItems {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 0 5px !important;
  min-height: 45px !important;
}

/* 修正左侧和右侧图标区域的对齐 */
#leftSendForm,
#rightSendForm {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  height: 100% !important;
  margin: 0 !important;
}

/* 头像强制居中 */
#send_form img,
.embedded-avatar {
  margin: 0 !important;
  align-self: center !important;
}

/* --- 去除原版提示词 --- */
#send_textarea::placeholder {
  color: transparent !important;
  opacity: 0 !important;
  -webkit-text-fill-color: transparent !important;
  text-shadow: none !important;
}

/* --- 修正自定义提示词：位置微调，不挡光标 --- */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--custom-placeholder) !important;
  color: rgba(0, 0, 0, 0.4) !important;
  position: absolute !important;
  left: var(--placeholder-left) !important;
  top: var(--placeholder-top) !important;
  transform: translateY(-50%) !important;
  font-size: var(--placeholder-font-size) !important;
  pointer-events: none !important;
  z-index: 5 !important;
  white-space: nowrap !important;
}

/* === 四、气泡卡片容器 (.mes_block) === */

/* 解决气泡右侧空出 */
.mes_block .ch_name,
.mes_block .mes_text {
  width: 100%;
  box-sizing: border-box;
  margin: 0;
  padding-left: 0;
  padding-right: 0;
}

#sheld {
  width: 100vw !important;
  max-width: 100vw !important;
  left: 0 !important;
  margin: 0 !important;
  height: calc(100dvh - var(--bottomFormBlockSize));
  max-height: calc(100dvh - var(--bottomFormBlockSize));
}

#chat {
  width: 100% !important;
  max-width: 100% !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin: 0 !important;
  padding-top: var(--chat-top-padding) !important;
  padding-bottom: var(--chat-bottom-padding) !important;
}

.mes {
  width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  position: relative !important;
  overflow: visible !important;
  background: transparent !important;
  border: none !important;
  margin-bottom: 50px !important;
}

.mes .mes_block {
  margin: 0 !important;
  width: var(--mes-block-width) !important;
  max-width: var(--mes-block-width) !important;
  min-height: 220px;
  position: relative !important;
  padding: 160px 15px 30px 15px !important;

  /* 背景：灰点 + 双色底 (浅灰/白) */
  background-image:
    radial-gradient(rgba(0, 0, 0, 0.15) 1.5px, transparent 1.5px),
    linear-gradient(to bottom, var(--card-header-bg) 110px, var(--card-body-bg) 110px) !important;
  background-size: 12px 12px, 100% 100% !important;
  background-repeat: repeat, no-repeat !important;

  /* 饼干形状保留，边框改为黑灰色 */
  border-radius: 40px 50px 35px 60px / 55px 35px 60px 45px !important;
  border: 4px solid #444444 !important;
  box-shadow: 0 6px 0 #CCCCCC, 0 12px 20px rgba(0, 0, 0, 0.1) !important;
  overflow: visible !important;
}

/* ===== 气泡右上角：熊猫趴趴 ===== */
.mes_block::after {
  content: "" !important;
  position: absolute !important;
  top: 35px !important;
  right: 30px !important;
  width: 100px !important;
  height: 70px !important;
  background-image: url("https://i.postimg.cc/JzGcZDj3/wu-biao-ti74-20260212123634-edit-823811543147509.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  z-index: 5 !important;
  pointer-events: none !important;
  transform: rotate(5deg) !important;
  filter: drop-shadow(2px 2px 0px rgba(0, 0, 0, 0.2));
}

/* 适配移动端 */
@media (max-width: 500px) {
  .mes_block::after {
    width: 90px !important;
    height: 70px !important;
    top: 10px !important;
    right: 15px !important;
    opacity: 0.8 !important;
  }
}

/* ===== 气泡右下角：熊猫写字板装饰 ===== */
.mes_block::before {
  content: "" !important;
  position: absolute !important;
  bottom: -10px !important;
  right: -5px !important;
  width: 50px !important;
  height: 80px !important;
  background-image: url("https://i.postimg.cc/FsqGPVFt/wu-biao-ti75-20260212130003.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: right bottom !important;
  z-index: 20 !important;
  pointer-events: none !important;
  transform: rotate(35deg) !important;
  filter: drop-shadow(4px 4px 0px rgba(0, 0, 0, 0.2)) !important;
}

/* === 3. 上半部分 (Header)：头像与名字 === */

/* 头像 (熊猫/角色) */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: 25px !important;
  left: 30px !important;
  width: 80px !important;
  height: 80px !important;
  z-index: 10 !important;
  padding: 0 !important;
  order: unset !important;
}

/* === 头像框装饰 === */
.mes .mesAvatarWrapper::before {
  content: "" !important;
  position: absolute !important;
  width: 85px !important;
  height: 85px !important;
  top: -5px !important;
  left: -4px !important;
  background-image: url("https://i.postimg.cc/R0LRVQvW/wu-biao-ti72-20260212120530.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  z-index: 20 !important;
  pointer-events: none !important;
}

.mes .avatar img {
  width: 80px !important;
  height: 80px !important;
  border-radius: 50% !important;
  border: 4px solid #FFFFFF !important;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* 名字 */
.mes .name_text {
  position: absolute !important;
  top: 20px !important;
  left: 115px !important;
  width: auto !important;
  font-size: 22px !important;
  font-weight: 800 !important;
  color: var(--text-color) !important;
  z-index: 10 !important;
  text-shadow: 1px 1px 0 #FFF;
}

.mes .name_text::after {
  display: block !important;
  white-space: pre-wrap !important;
  max-width: 220px !important;
  word-break: break-word !important;
  margin-top: 10px !important;
  font-size: 13px !important;
  line-height: 1.2 !important;
  font-weight: 400 !important;
  color: #777777 !important;
  text-shadow:
    1.5px 1.5px 0px #FFF,
    -1.5px -1.5px 0px #FFF,
    1.5px -1.5px 0px #FFF,
    -1.5px 1.5px 0px #FFF,
    3px 3px 0px rgba(0, 0, 0, 0.2) !important;
  opacity: 1 !important;
  transition: all 0.3s ease;
  font-style: italic !important;
}

/* 区分角色和用户的变量内容 */
.mes:not([is_user="true"]) .name_text::after {
  content: var(--char-slogan) !important;
}

.mes[is_user="true"] .name_text::after {
  content: var(--user-slogan) !important;
}

/* === 4. 下半部分 (Dashboard)：固定大小的方块，色块改为灰阶 === */

/* 公共方块样式：锁定尺寸 */
.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
  position: absolute !important;
  top: 105px !important;
  height: 38px !important;
  width: 72px !important;
  min-width: unset !important;
  max-width: 72px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 12px !important;
  font-size: 13px !important;
  font-weight: 800 !important;
  color: var(--text-color) !important;
  padding: 0 4px !important;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.03) !important;
  z-index: 50 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  background-clip: padding-box !important;
  opacity: 1 !important;
}

/* 4.1 方块一：ID */
.mes .mesIDDisplay {
  left: -10px !important;
  background-color: var(--block-1) !important;
}

.mes .mesIDDisplay::before {
  content: "📅" !important;
  margin-right: 3px;
  font-size: 13px;
  position: static !important;
  width: auto !important;
}

/* 4.2 方块二：Token */
.mes .tokenCounterDisplay {
  left: 72px !important;
  background-color: var(--block-2) !important;
}

.mes .tokenCounterDisplay::before {
  content: "🎓" !important;
  margin-right: 3px;
  font-size: 13px;
  position: static !important;
  width: auto !important;
}

/* 4.3 方块三：Timer */
.mes .mes_timer {
  left: 154px !important;
  background-color: var(--block-3) !important;
}

.mes .mes_timer::before {
  content: "⏰" !important;
  margin-right: 3px;
  font-size: 13px;
  position: static !important;
  width: auto !important;
}

.mesIDDisplay:empty::after {
  content: "0";
}

.tokenCounterDisplay:empty::after {
  content: "0t";
}

.mes_timer:empty::after {
  content: "0s";
}

/* === 4.4 修正版：方块四 (装饰性灰色盒子) === */
.mes .mesAvatarWrapper::after {
  content: "🐼 panda" !important;
  position: absolute !important;
  top: 105px !important;
  left: 236px !important;
  width: 72px !important;
  height: 38px !important;
  background-color: var(--block-4) !important;
  border-radius: 12px !important;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.03) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 14px !important;
  color: var(--text-color) !important;
  z-index: 50 !important;
  pointer-events: none !important;
}

/* 移动端防溢出保护 */
@media (max-width: 360px) {
  .mes .mesAvatarWrapper::after {
    display: none !important;
  }
}

.mes .mes_block .ch_name {
  display: contents !important;
}

/* --- 1. 将小铅笔和三个点挪到上半部分 (Header区) --- */
.mes .mes_buttons {
  position: absolute !important;
  top: 85px !important;
  right: 15px !important;
  left: auto !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
  gap: 8px !important;
  min-width: unset !important;
  color: var(--text-color) !important;
  z-index: 15;
}

/* 小铅笔 */
.mes .mes_edit,
.mes .extraMesButtonsHint {
  box-shadow: none !important;
  filter: none !important;
}

/* ===== 聊天时间戳：右上角圆钝大招牌 (黑白版) ===== */
.mes .timestamp {
  position: absolute !important;
  top: -18px !important;
  right: 30px !important;
  left: auto !important;
  transform: none !important;
  opacity: 1 !important;
  background-color: #555555 !important;
  color: #FFFFFF !important;
  visibility: visible !important;
  display: block !important;
  font-size: 13px !important;
  font-weight: 900 !important;
  padding: 6px 28px !important;
  min-width: 100px !important;
  text-align: center !important;
  white-space: nowrap !important;
  clip-path: polygon(0% 0%, 100% 0%, calc(100% - 6px) 50%, 100% 100%, 0% 100%, 6px 50%) !important;
  letter-spacing: 1px !important;
  z-index: 100 !important;
  border: none !important;
  box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.3) !important;
}

