  z-index: 10;
  margin: 0 !important;
}

/* --- 3. 右导航箭头：深灰图标 --- */
.swipe_right {
  position: absolute !important;
  right: 25px !important;
  bottom: 15px !important;
  left: auto !important;
  color: #555555 !important;
  font-size: 15px !important;
  opacity: 1 !important;
  text-shadow: none !important;
}

/* --- 4. 左导航箭头：深灰图标 --- */
.swipe_left {
  position: absolute !important;
  left: 25px !important;
  bottom: 15px !important;
  right: auto !important;
  color: #555555 !important;
  font-size: 15px !important;
  opacity: 1 !important;
  text-shadow: none !important;
}

/* ===== 彻底美化加载组件 (#load-spinner) 小熊猫 ===== */
#load-spinner {
  background: none !important;
  background-image: url("https://i.postimg.cc/HLTZq0KQ/wu-biao-ti82-20260212144439.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 150px !important;
  height: 150px !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  animation: bearFloat 1.5s infinite ease-in-out !important;
  filter: drop-shadow(4px 4px 0px rgba(0, 0, 0, 0.2)) !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  margin-top: -75px !important;
  margin-left: -75px !important;
}

/* 彻底杀掉 spinner 内部可能存在的 FontAwesome 齿轮字符 */
#load-spinner::before,
#load-spinner::after {
  display: none !important;
  content: none !important;
}

/* 2. 定义小熊悬浮动画 (保留) */
@keyframes bearFloat {

  0%,
  100% {
    transform: translateY(0) scale(1);
  }

  50% {
    transform: translateY(-15px) scale(1.05);
  }
}

/* 3. 顺便把大背景改掉 */
#preloader {
  background-color: #FFFFFF !important;
  background-image: radial-gradient(#AAAAAA 1.5px, transparent 1.5px) !important;
  background-size: 24px 24px !important;
}

